local CrucibleMaker = {}
local PRODUCTS = {
    iron_crucible = { name = "Železni talilni lonec", ironCost = 4, woodCost = 1, leatherCost = 1, time = 6, cost = 195, prestige = 4, happiness = 2, description = "Železni talilni lonec za taljenje kovin." },
    bronze_crucible = { name = "Bronast talilni lonec", bronzeCost = 4, ironCost = 1, woodCost = 1, leatherCost = 1, time = 8, cost = 470, prestige = 6, happiness = 3, description = "Bronast talilni lonec za visoke temperature." },
    silver_crucible = { name = "Srebrni talilni lonec", silverCost = 4, bronzeCost = 1, ironCost = 1, woodCost = 1, leatherCost = 1, time = 12, cost = 1130, prestige = 11, happiness = 4, description = "Srebrni talilni lonec za plemiške livarje." },
    gilded_crucible = { name = "Pozlačeni talilni lonec", goldCost = 1, silverCost = 4, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 16, cost = 2420, prestige = 20, happiness = 5, description = "Pozlačeni talilni lonec za dvorne livarje." },
    jewel_set_crucible = { name = "Draguljasti talilni lonec", goldCost = 2, silverCost = 4, jewelCost = 1, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 20, cost = 5200, prestige = 36, happiness = 7, description = "Draguljasti talilni lonec za kraljevske livarje." },
    royal_sovereign_crucible = { name = "Kraljevski suvereni talilni lonec", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 27, cost = 11100, prestige = 69, happiness = 13, description = "Suvereni talilni lonec z biseri za krono." },
}
local BUILDINGS = {
    crucible_workshop = { name = "Talilna delavnica", cost = { gold = 370, wood = 175, stone = 150, iron = 10 }, upkeep = 7, qualityBonus = 5 },
    crucible_house = { name = "Talilna hiša", cost = { gold = 1285, wood = 360, stone = 290, silver = 8, iron = 8 }, upkeep = 27, qualityBonus = 18 },
    master_crucible_atelier = { name = "Mojstrski talilni atelje", cost = { gold = 3200, wood = 420, stone = 545, silver = 39, gold = 8 }, upkeep = 75, qualityBonus = 30 },
    sovereign_crucible_palace = { name = "Suverena talilna palača", cost = { gold = 13600, wood = 650, stone = 860, gold = 88, jewel = 20 }, upkeep = 263, qualityBonus = 55, prestigeBonus = 50 },
}
CrucibleMaker.ironStock = 16; CrucibleMaker.bronzeStock = 14; CrucibleMaker.woodStock = 10; CrucibleMaker.leatherStock = 8; CrucibleMaker.silverStock = 8; CrucibleMaker.goldStock = 6; CrucibleMaker.jewelStock = 4; CrucibleMaker.pearlStock = 4
CrucibleMaker.productStock = {}; CrucibleMaker.buildings = {}; CrucibleMaker.maker = nil; CrucibleMaker.activeMaking = {}; CrucibleMaker.totalProducts = 0; CrucibleMaker.dayTimer = 0
function CrucibleMaker.init() CrucibleMaker.ironStock=16; CrucibleMaker.bronzeStock=14; CrucibleMaker.woodStock=10; CrucibleMaker.leatherStock=8; CrucibleMaker.silverStock=8; CrucibleMaker.goldStock=6; CrucibleMaker.jewelStock=4; CrucibleMaker.pearlStock=4; CrucibleMaker.productStock={}; CrucibleMaker.buildings={}; CrucibleMaker.maker=nil; CrucibleMaker.activeMaking={}; CrucibleMaker.totalProducts=0; CrucibleMaker.dayTimer=0; print("[CrucibleMaker] Royal Crucible Maker System initialized (6 products, 4 buildings)") end
function CrucibleMaker.hireMaker(n,s) s=s or math.random(55,90); local c=595+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CrucibleMaker.maker={name=n or ("Talilnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Talilnik najet: %s (spretnost: %d)",CrucibleMaker.maker.name,s),"success") end; return true end
function CrucibleMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CrucibleMaker.build(id) local ok,e=CrucibleMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CrucibleMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CrucibleMaker.getQualityBonus() local b=0; for _,bd in ipairs(CrucibleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CrucibleMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and CrucibleMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and CrucibleMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and CrucibleMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and CrucibleMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and CrucibleMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CrucibleMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CrucibleMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CrucibleMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CrucibleMaker.buildings==0 then return false,"Potrebna talilna delavnica" end; if not CrucibleMaker.maker then return false,"Potreben talilnik" end; return true end
function CrucibleMaker.make(pt,qty) qty=qty or 1; local ok,e=CrucibleMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then CrucibleMaker.ironStock=CrucibleMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then CrucibleMaker.bronzeStock=CrucibleMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then CrucibleMaker.woodStock=CrucibleMaker.woodStock-d.woodCost*qty end; if d.leatherCost then CrucibleMaker.leatherStock=CrucibleMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then CrucibleMaker.silverStock=CrucibleMaker.silverStock-d.silverCost*qty end; if d.goldCost then CrucibleMaker.goldStock=CrucibleMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CrucibleMaker.jewelStock=CrucibleMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CrucibleMaker.pearlStock=CrucibleMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CrucibleMaker.maker then t=math.max(1,t-math.floor(CrucibleMaker.maker.skill/13)) end; table.insert(CrucibleMaker.activeMaking,{id="crucible_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CrucibleMaker.completeMaking(m) local q=1.0+(CrucibleMaker.getQualityBonus()/100); if CrucibleMaker.maker then q=q+(CrucibleMaker.maker.skill/140) end; q=math.min(2.5,q); CrucibleMaker.productStock[m.productType]=(CrucibleMaker.productStock[m.productType] or 0)+m.quantity; CrucibleMaker.totalProducts=CrucibleMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CrucibleMaker.maker then CrucibleMaker.maker.itemsMade=CrucibleMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CrucibleMaker.maker.skill=math.min(100,CrucibleMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Talilni lonec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"crucible.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function CrucibleMaker.update(dt) if not _G.state then return end; CrucibleMaker.dayTimer=CrucibleMaker.dayTimer+dt; if CrucibleMaker.dayTimer>=30 then CrucibleMaker.dayTimer=0; for i=#CrucibleMaker.activeMaking,1,-1 do local m=CrucibleMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CrucibleMaker.completeMaking(m); table.remove(CrucibleMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CrucibleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CrucibleMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CrucibleMaker.getStats() return {ironStock=CrucibleMaker.ironStock,bronzeStock=CrucibleMaker.bronzeStock,woodStock=CrucibleMaker.woodStock,leatherStock=CrucibleMaker.leatherStock,silverStock=CrucibleMaker.silverStock,goldStock=CrucibleMaker.goldStock,jewelStock=CrucibleMaker.jewelStock,pearlStock=CrucibleMaker.pearlStock,productStock=CrucibleMaker.productStock,numBuildings=#CrucibleMaker.buildings,hasMaker=CrucibleMaker.maker~=nil,makerName=CrucibleMaker.maker and CrucibleMaker.maker.name or "—",makerSkill=CrucibleMaker.maker and CrucibleMaker.maker.skill or 0,activeMaking=#CrucibleMaker.activeMaking,totalProducts=CrucibleMaker.totalProducts} end
return CrucibleMaker
